      "infografico_ilustrado": "<div style='padding:22px;border-radius:18px;background:#0f172a;border:1px solid #334155;'><div style='font-weight:800;font-size:1.05em;color:#e0e7ff;margin-bottom:16px;'>📊 INFOGRÁFICO EXPLICATIVO — SIMBOLISMO NO BRASIL E EM PORTUGAL</div><div style='display:flex;flex-direction:column;gap:12px;'><div style='background:#1e293b;border:1px solid #334155;border-left:5px solid #818cf8;border-radius:14px;padding:18px;display:flex;gap:14px;align-items:flex-start;'><div style='background:#818cf822;color:#818cf8;font-weight:900;font-size:1.1em;min-width:44px;height:44px;border-radius:12px;display:flex;align-items:center;justify-content:center;flex-shrink:0;'>📌</div><div style='flex:1;'><div style='font-size:0.75em;font-weight:800;color:#818cf8;letter-spacing:1px;margin-bottom:4px;'>ETAPA 01</div><div style='color:#f1f5f9;font-size:0.98em;line-height:1.68;'>Recurso Visual Sugerido: Painel em 3 blocos (Bloco 1: O que é Simbolismo e Pré-Modernismo no Brasil; Bloco 2: Esquema visual passo a passo; Bloco 3: Exemplo resolvido).</div></div></div><div style='background:#1e293b;border:1px solid #334155;border-left:5px solid #34d399;border-radius:14px;padding:18px;display:flex;gap:14px;align-items:flex-start;'><div style='background:#34d39922;color:#34d399;font-weight:900;font-size:1.1em;min-width:44px;height:44px;border-radius:12px;display:flex;align-items:center;justify-content:center;flex-shrink:0;'>⚙️</div><div style='flex:1;'><div style='font-size:0.75em;font-weight:800;color:#34d399;letter-spacing:1px;margin-bottom:4px;'>ETAPA 02</div><div style='color:#f1f5f9;font-size:0.98em;line-height:1.68;'>Referência Visual: Buscar infográficos educacionais sobre \"Simbolismo e Pré-Modernismo no Brasil 1. Língua Portuguesa\" no portal Toda Matéria ou Brasil Escola.</div></div></div></div></div>",
      "fluxograma_decisao": "<div style='display:flex;flex-direction:column;align-items:center;gap:8px;padding:20px;background:#0f172a;border-radius:18px;border:1px solid #334155;'><div style='background:linear-gradient(135deg,#4f46e5,#6366f1);color:#f8fafc;border:none;padding:14px 22px;border-radius:12px;font-weight:600;text-align:center;max-width:480px;width:100%;line-height:1.6;'>Início: Analisar a questão sobre Simbolismo e Pré-Modernismo no Brasil</div><div style='font-size:1.3em;color:#818cf8;font-weight:bold;line-height:1;'>⬇</div><div style='background:#1e293b;color:#f8fafc;border:1px solid #6366f1;padding:14px 22px;border-radius:12px;font-weight:600;text-align:center;max-width:480px;width:100%;line-height:1.6;'>Identificar os dados/elementos fornecidos</div><div style='font-size:1.3em;color:#818cf8;font-weight:bold;line-height:1;'>⬇</div><div style='background:#1e293b;color:#f8fafc;border:1px solid #6366f1;padding:14px 22px;border-radius:12px;font-weight:600;text-align:center;max-width:480px;width:100%;line-height:1.6;'>Verificar se há exceção ou condição especial</div><div style='font-size:1.3em;color:#818cf8;font-weight:bold;line-height:1;'>⬇</div><div style='background:#1e293b;color:#f8fafc;border:1px solid #6366f1;padding:14px 22px;border-radius:12px;font-weight:600;text-align:center;max-width:480px;width:100%;line-height:1.6;'>Aplicar a regra/fórmula correspondente</div><div style='font-size:1.3em;color:#818cf8;font-weight:bold;line-height:1;'>⬇</div><div style='background:linear-gradient(135deg,#059669,#10b981);color:#f8fafc;border:none;padding:14px 22px;border-radius:12px;font-weight:600;text-align:center;max-width:480px;width:100%;line-height:1.6;'>Validar a resposta final</div></div>",
